// Deterministic primality test for u64 using trial division up to sqrt(n).
// Exact (not probabilistic) and avoids overflow by using f <= n / f.

pub fn divides(factor: u64, candidate: u64) -> bool {
    candidate % factor == 0
}

pub fn is_prime(candidate: u64) -> bool {
    test_prime(candidate)
}

pub fn test_prime(candidate: u64) -> bool {
    // Problem statement says candidate > 1, but keep a defensive guard.
    if candidate <= 1 {
        return false;
    }
    if candidate <= 3 {
        return true; // 2 and 3 are prime
    }
    if candidate % 2 == 0 {
        return false; // even and > 2
    }

    let mut f: u64 = 3;
    // Use f <= candidate / f to avoid overflow vs f*f <= candidate.
    while f <= candidate / f {
        if candidate % f == 0 {
            return false;
        }
        f += 2;
    }
    true
}

